 8→// Tracker manages the lifecycle of improvement suggestions.
 9→type Tracker struct {
10→	Records map[string]*SuggestionRecord
11→}
12→
13→// NewTracker creates a new Tracker with an empty record map.
14→func NewTracker() *Tracker {
15→	return &Tracker{Records: make(map[string]*SuggestionRecord)}
16→}
17→
18→// AddSuggestion registers a new suggestion.
19→func (t *Tracker) AddSuggestion(rec SuggestionRecord) {
20→	t.Records[rec.ID] = &rec
21→}
22→
23→// Get returns a suggestion by ID, or nil if not found.
24→func (t *Tracker) Get(id string) *SuggestionRecord {
25→	return t.Records[id]
26→}
27→
28→// Accept marks a suggestion as accepted and records the resolution time.
29→func (t *Tracker) Accept(id string) error {
30→	rec, ok := t.Records[id]
31→	if !ok {
32→		return fmt.Errorf("suggestion %q not found", id)
33→	}
34→	now := time.Now()
35→	rec.Status = "accepted"
36→	rec.ResolvedAt = &now
37→	return nil
38→}
